#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.bomb)]
    public class Bomb : EnemyBehaviour, IDeathEffectsBehaviour
    {
        public Bomb(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new ColorModifier(EngineEntityProps.COLOR_OFFSET, PROP_COLOR_OFFSET));
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.Timeout = entity.GetMaxTimeout();
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);

            if (entity.Timeout >= 0)
            {
                entity.Timeout--;
                if (entity.Timeout <= 0)
                {
                    entity.Die(new DamageEffectList(VanillaDamageEffects.NO_NEUTRALIZE), entity);
                }
            }
            if (entity.Timeout == 30)
            {
                entity.PlaySound(VanillaSoundID.fuse);
            }
            Color color = Color.clear;
            if (entity.Timeout <= 30 && entity.Timeout % 4 < 2)
            {
                color = Color.white;
            }
            entity.SetProperty(PROP_COLOR_OFFSET, color);
        }
        public void DeathEffects(Entity entity, DeathInfo info)
        {
            if (info.Effects.HasEffect(VanillaDamageEffects.REMOVE_ON_DEATH))
                return;
            if (info.Effects.HasEffect(VanillaDamageEffects.DROWN))
                return;
            Skelebomb.Explode(entity, entity.GetDamage() * 3, entity.GetFaction(), entity.GetCenter());
            entity.Remove();
        }
        public static readonly VanillaEntityPropertyMeta<Color> PROP_COLOR_OFFSET = new VanillaEntityPropertyMeta<Color>("ColorOffset");
    }
}
